import pathlib,html,re
src=pathlib.Path('products/services/welfare-tender/brief-en-fr.md').read_text()
body=[]
for line in src.splitlines():
  l=html.escape(line)
  l=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',l)
  l=re.sub(r'(https://[^\s)]+)',r'<a href="\1" rel="nofollow">\1</a>',l)
  if line.startswith('# '): body.append('<h1>'+l[2:]+'</h1>')
  elif line.startswith('## '): body.append('<h2>'+l[3:]+'</h2>')
  elif line.startswith('- '): body.append('<li>'+l[2:]+'</li>')
  elif re.match(r'\d+\. ',line): body.append('<li>'+l.split('. ',1)[1]+'</li>')
  elif line.strip(): body.append('<p>'+l+'</p>')
